#include <optional>
#include <sstream>
#include <string>
#include <utility>
#include <vector>

struct Player
{
    int x, y, health, maxHealth, power, armour;
    std::vector<std::pair<std::string, int>> inventory;
};

std::string savePlayer(const Player& p)
{
    std::ostringstream out;
    out << "player " << p.x << ' ' << p.y << " hp " << p.health << ' ' << p.maxHealth
        << " power " << p.power << " armour " << p.armour << '\n';
    for (const auto& [id, count] : p.inventory) out << "inv " << id << ' ' << count << '\n';
    return out.str();
}

std::optional<Player> loadPlayer(const std::string& text)
{
    Player p{};
    bool havePlayer{ false };
    std::istringstream in{ text };
    std::string line;
    while (std::getline(in, line))
    {
        std::istringstream fields{ line };
        std::string keyword;
        if (!(fields >> keyword)) continue;                              // blank line
        if (keyword == "player")
        {
            std::string hp, power, armour, extra;
            if (!(fields >> p.x >> p.y >> hp >> p.health >> p.maxHealth >> power >> p.power >> armour >> p.armour)) return std::nullopt;
            if (hp != "hp" || power != "power" || armour != "armour" || (fields >> extra)) return std::nullopt;
            havePlayer = true;
        }
        else if (keyword == "inv")
        {
            std::string id, extra;
            int count{ 0 };
            if (!(fields >> id >> count) || count < 1 || (fields >> extra)) return std::nullopt;
            p.inventory.push_back({ id, count });
        }
        // any other keyword: from a newer version, ignored
    }
    if (!havePlayer) return std::nullopt;
    return p;
}

unitTests:
const Player hero{ 7, 4, 14, 20, 4, 1, { { "potion", 3 }, { "dagger", 1 } } };
TEST("the exact text") { CHECK_EQ(savePlayer(hero), std::string("player 7 4 hp 14 20 power 4 armour 1
inv potion 3
inv dagger 1
")); }
TEST("round trip")
{
    const auto p{ loadPlayer(savePlayer(hero)) };
    CHECK(p.has_value());
    CHECK_EQ(p->x, 7); CHECK_EQ(p->health, 14); CHECK_EQ(p->maxHealth, 20); CHECK_EQ(p->armour, 1);
    CHECK_EQ(p->inventory.size(), std::size_t{ 2 });
    CHECK_EQ(p->inventory[1].first, std::string("dagger"));
}
TEST("any order, blank lines and unknown keywords") { const auto p{ loadPlayer("inv gold 40

weather rain
player 1 2 hp 3 4 power 5 armour 6
") }; CHECK(p.has_value()); CHECK_EQ(p->power, 5); CHECK_EQ(p->inventory[0].second, 40); }
TEST("an empty inventory") { const auto p{ loadPlayer("player 0 0 hp 1 1 power 1 armour 0
") }; CHECK(p.has_value()); CHECK(p->inventory.empty()); }
TEST("missing player line") { CHECK(!loadPlayer("inv potion 1
").has_value()); CHECK(!loadPlayer("").has_value()); }
TEST("malformed player line") { CHECK(!loadPlayer("player 1 2 hp 3
").has_value()); CHECK(!loadPlayer("player 1 2 health 3 4 power 5 armour 6
").has_value()); CHECK(!loadPlayer("player a 2 hp 3 4 power 5 armour 6
").has_value()); }
TEST("malformed inventory lines") { CHECK(!loadPlayer("player 1 2 hp 3 4 power 5 armour 6
inv potion
").has_value()); CHECK(!loadPlayer("player 1 2 hp 3 4 power 5 armour 6
inv potion 0
").has_value()); }

